) {
  _ = &offsets;
  _ = &neighbors;
  _ = &weights;
  _ = &rowPositions;
  _ = &pairs;
  _ = &parameters;
  _ = &observedRaw;
  _ = &exceedances;
  _ = INVOCATION_COUNT;
  let workgroupIndex =
    (workgroupId.z * WGSL_KERNEL_DISPATCH_Y + workgroupId.y) * WGSL_KERNEL_DISPATCH_X +
    workgroupId.x;
