  let lowHigh = aLow * bHigh;
  let highLow = aHigh * bLow;
  let highHigh = aHigh * bHigh;
  let middle = (lowLow >> 16u) + (lowHigh & 0xffffu) + (highLow & 0xffffu);
  return highHigh + (lowHigh >> 16u) + (highLow >> 16u) + (middle >> 16u);
