    var stream = createPhiloxStream(key, index, permutation, RANDOM_TAG);
    var swapPositions: array<u32, 4>;
    var swapValues: array<u32, 4>;
    var swapCount = 0u;
    var lagA = 0.0;
    var lagB = 0.0;
    for (var drawn = 0u; drawn < neighborTotal; drawn++) {
