) {
  _ = &offsets;
  _ = &neighbors;
  _ = &weights;
  _ = &rowPositions;
  _ = &pairs;
  _ = &parameters;
  _ = &observedRaw;
  _ = &exceedances;
  _ = INVOCATION_COUNT;
