  let fy = getY(position);
  let permutations = readValidPermutationCount();
  let key = readSeedKey();
  var greater = 0u;
  var lesser = 0u;
  var folded = 0u;
  var total = 0.0;
  var mean = 0.0;
  // The row's active neighbor weights in slot order, read once: a permutation only reassigns
  // values to slots, so the per-draw work is the random draw and one value gather, not four
  // CSR gathers (offsets, neighbor, neighbor position, weight) per slot per permutation.
  var slotWeights: array<f32, 4>;
  var neighborTotal = 0u;
  {
    let activeRow = index;
    let activeBegin = min(offsets[offsetsOffset + activeRow], CAPACITY);
    let activeEnd = min(offsets[offsetsOffset + activeRow + 1u], CAPACITY);
    for (var slot = activeBegin; slot < activeEnd; slot++) {
      let neighbor = neighbors[neighborsOffset + slot];
      if (neighbor >= ROWS || neighbor == activeRow) {
        continue;
      }
      let weight = weights[weightsOffset + slot];
      if (!(weight > 0.0) || !(rowPositions[rowPositionsOffset + neighbor] != INVALID_POSITION)) {
        continue;
      }
      if (neighborTotal < MAXIMUM_NEIGHBORS) {
      slotWeights[neighborTotal] = 1.0;
      neighborTotal++;
    }
    }
  }
