// Bits per Feistel half for a domain of count values; equals the TypeScript getFeistelHalfBits.
fn getFeistelHalfBits(count: u32) -> u32 {
  let bits = max(select(32u - countLeadingZeros(count - 1u), 1u, count <= 1u), 2u);
