      let neighbor = neighbors[neighborsOffset + slot];
      if (neighbor >= ROWS || neighbor == activeRow) {
        continue;
      }
      let weight = weights[weightsOffset + slot];
      if (!(weight > 0.0) || !(rowPositions[rowPositionsOffset + neighbor] != INVALID_POSITION)) {
        continue;
      }
