    if (min(greater, lesser) >= STOP_AFTER_EXCEEDANCES) {
      permutationsRun = permutation + 1u;
      break;
    }
  }
  mean = total / f32(permutations);
  }
  exceedances[exceedancesOffset + index] = min(greater, lesser);
  exceedances[exceedancesOffset + ROWS + index] = permutationsRun;
}

