    let low0 = PHILOX_M0 * c.x;
    let high1 = getPhiloxMultiplyHigh(PHILOX_M1, c.z);
    let low1 = PHILOX_M1 * c.z;
    c = vec4<u32>(high1 ^ c.y ^ k.x, low1, high0 ^ c.w ^ k.y, low0);
